  explicacion: `La dosis estándar de alteplasa para EVC isquémico es 0.9 mg/kg, con un máximo de 90 mg. Se administra el 10% como bolo intravenoso y el 90% restante en infusión durante 60 minutos. Antes de iniciarla deben confirmarse la elegibilidad y las contraindicaciones.`,
  perlaENARM: "Alteplasa: 0.9 mg/kg, máximo 90 mg; 10% en bolo y 90% durante una hora.",
