  caso: `Mujer de 32 años presenta dolor de cabeza bilateral, opresivo, de intensidad leve a moderada. Puede continuar sus actividades y no presenta vómitos ni empeoramiento importante con la actividad física habitual.`,
  pregunta: "¿Qué tipo de cefalea es más probable?",
