  respuestaCorrecta: 0,
  explicacion: `El papiledema es la inflamación del disco óptico secundaria al aumento de presión intracraneal y constituye un hallazgo de alarma. Requiere evaluación urgente de posibles causas estructurales o vasculares antes de realizar procedimientos que puedan aumentar el riesgo.`,
  perlaENARM: "Papiledema con cefalea progresiva exige investigar hipertensión intracraneal.",
