  tema: "Neuropatías periféricas",
  subtema: "Polineuropatía diabética",
  dificultad: "Media",
  caso: `Mujer de 62 años con diabetes de larga evolución presenta hormigueo simétrico en los pies, menor percepción del monofilamento y ausencia de reflejos aquíleos.`,
  pregunta: "¿Cuál es una causa frecuente de este patrón clínico?",
