  caso: `Varón de 71 años con enfermedad de Parkinson presenta bradicinesia y rigidez que dificultan vestirse y caminar. Los síntomas interfieren de forma importante con su vida cotidiana.`,
  pregunta: "¿Qué fármaco mejora los síntomas motores al aumentar la disponibilidad cerebral de dopamina?",
