  respuestaCorrecta: 0,
  explicacion: `La levodopa atraviesa la barrera hematoencefálica y se convierte en dopamina. La carbidopa reduce su conversión periférica y disminuye efectos adversos periféricos. Es uno de los tratamientos sintomáticos más eficaces para los síntomas motores de Parkinson.`,
  perlaENARM: "Levodopa/carbidopa es un tratamiento sintomático fundamental para el Parkinson con repercusión funcional.",
