  tema: "Síndrome de Guillain-Barré",
  subtema: "Tratamiento específico",
  dificultad: "Media",
  caso: `Varón de 45 años con Guillain-Barré presenta debilidad progresiva y dificultad para caminar. Los síntomas comenzaron hace una semana y el equipo decide iniciar tratamiento inmunomodulador.`,
  pregunta: "¿Qué tratamiento ha demostrado beneficio en Guillain-Barré?",
  opciones: [
    "Inmunoglobulina intravenosa o plasmaféresis",
    "Corticoides orales como monoterapia estándar",
    "Levodopa",
    "Riluzol",
    "Antibióticos en todos los casos, independientemente de la causa"
  ],
  respuestaCorrecta: 0,
  explicacion: `La inmunoglobulina intravenosa y la plasmaféresis son tratamientos eficaces en Guillain-Barré cuando están indicados. Los glucocorticoides no han demostrado beneficio como tratamiento estándar. También son fundamentales la vigilancia respiratoria, el manejo de la disautonomía y la rehabilitación.`,
  perlaENARM: "Guillain-Barré: IVIG o plasmaféresis; los corticoides no son tratamiento estándar eficaz.",
