  tema: "Miastenia gravis",
  subtema: "Medicamentos que pueden agravar la debilidad",
  dificultad: "Media",
  caso: `Mujer de 40 años con miastenia gravis estable desarrolla una infección bacteriana. El médico revisa los medicamentos antes de seleccionar el antibiótico.`,
