  opciones: [
    "Aminoglucósidos",
    "Antiácidos simples en dosis habituales",
    "Soluciones salinas isotónicas",
    "Laxantes osmóticos en todos los casos",
    "Suplementos de fibra"
  ],
  respuestaCorrecta: 0,
  explicacion: `Los aminoglucósidos pueden alterar la transmisión neuromuscular y empeorar la debilidad en pacientes con miastenia gravis. La selección antibiótica debe considerar la infección, las alternativas disponibles y los riesgos individuales, sin dejar de tratar una infección grave.`,
  perlaENARM: "En miastenia gravis, revisar fármacos que empeoran la transmisión neuromuscular, incluidos aminoglucósidos.",
